def test_put_validation_error() -> None:
    """Tests PUT with invalid data returns 422."""
    base = os.environ.get("SUT_URL", "http://127.0.0.1:8000")
    url = f"{base}/fixtures/put_validation_error/items/1"
    _headers = {
        "Content-Type": "application/json",
    }
    _headers.setdefault("Content-Type", "application/json")
    _body = json.dumps({"id": 1, "name": "X", "price": -10}).encode()
    _req = urllib.request.Request(url, data=_body, headers=_headers, method="PUT")  # noqa: S310

    class _NoRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self, *args, **kwargs):  # noqa: ANN002, ANN003, ANN202, ARG002
            return None

    _opener = urllib.request.build_opener(_NoRedirect())
    try:
        response = _opener.open(_req)
        status_code = response.status
        resp_body = response.read()
        resp_headers = dict(response.headers)
    except urllib.error.HTTPError as _exc:
        status_code = _exc.code
        resp_body = _exc.read()
        resp_headers = dict(_exc.headers)  # noqa: F841
    assert status_code == 422
    data = json.loads(resp_body)
    assert data == {
        "detail": "2 validation errors in request",
        "errors": [
            {
                "ctx": {"min_length": 3},
                "input": "X",
                "loc": ["body", "name"],
                "msg": "String should have at least 3 characters",
                "type": "string_too_short",
            },
            {
                "ctx": {"gt": 0},
                "input": -10,
                "loc": ["body", "price"],
                "msg": "Input should be greater than 0",
                "type": "greater_than",
            },
        ],
        "status": 422,
        "title": "Request Validation Failed",
        "type": "https://spikard.dev/errors/validation-error",
    }
